def get_guidance(category):
    if not category: return None
    key = category.strip().lower().replace("_", "-").replace(" ", "-")
    aliases = {"biological-waste":"biological", "organic":"biological", "green-glass":"green-glass", "white-glass":"white-glass"}
    key = aliases.get(key, key)
    return GUIDES.get(key)
